197	func (s *store) listPins(now time.Time) []pinEntry {
198		s.mu.RLock()
199		defer s.mu.RUnlock()
200		entries := []pinEntry{}
201		for cid, p := range s.pins {
202			if validPin(p, now) {
203				entries = append(entries, pinEntry{cid: cid, expiresAt: p.expiresAt})
204			}
205		}
206		sort.Slice(entries, func(i, j int) bool { return entries[i].cid < entries[j].cid })
207		return entries
208	}
