// auditCapacity bounds the retained event history; older events are
// evicted while sequence numbers keep increasing.
const auditCapacity = 10000

// Audit actions, one per recorded entry point.
const (
	auditObjectUpload      = "object.upload"
	auditBundleImport      = "bundle.import"
	auditDeltaBundleImport = "delta_bundle.import"
	auditPinPut            = "pin.put"
	auditPinDelete         = "pin.delete"
	auditGCPreview         = "gc.preview"
	auditGCCollect         = "gc.collect"
	auditProviderPut       = "provider.put"
	auditProviderDelete    = "provider.delete"
	auditRetrievalLocal    = "retrieval.local"
	auditRetrievalFetch    = "retrieval.fetch"
)

// auditEvent is one recorded outcome. Fields that do not apply to an
// action are nil and serialize as null.
type auditEvent struct {
	Seq        int64     `json:"seq"`
	At         time.Time `json:"at"`
	Action     string    `json:"action"`
	CID        *string   `json:"cid"`
	Result     string    `json:"result"`
	Objects    *int      `json:"objects"`
	Bytes      *int      `json:"bytes"`
	ProviderID *string   `json:"providerId"`
}

// auditRecord carries the commit-time facts of one event; the log assigns
// the sequence number and timestamp at append.
type auditRecord struct {
	action     string
	result     string
	cid        *string
	objects    *int
	bytes      *int
	providerID *string
}

// auditLog is a process-local ring of recent audit events. Appends happen
// under the caller's business lock so event order matches commit order;
// the log never mutates business state and is not retained across restarts.
type auditLog struct {
	mu     sync.Mutex
	ring   []auditEvent
	start  int
	length int
	next   int64
}

func newAuditLog() *auditLog {
	return &auditLog{ring: make([]auditEvent, auditCapacity), next: 1}
}

// append records one event with the next sequence number.
func (a *auditLog) append(rec auditRecord) {
	if a == nil {
		return
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	ev := auditEvent{
		Seq:        a.next,
		At:         time.Now().UTC(),
		Action:     rec.action,
		CID:        rec.cid,
		Result:     rec.result,
		Objects:    rec.objects,
		Bytes:      rec.bytes,
		ProviderID: rec.providerID,
	}
	a.next++
	if a.length < auditCapacity {
		a.ring[(a.start+a.length)%auditCapacity] = ev
		a.length++
		return
	}
	a.ring[a.start] = ev
	a.start = (a.start + 1) % auditCapacity
}
```

