// snapshot returns up to limit retained events with seq > after in
// ascending order. expired reports that after points before the oldest
// retained event (other than the zero cursor). hasMore reports whether
// retained events beyond the returned page exist.
func (a *auditLog) snapshot(after int64, limit int) (events []auditEvent, hasMore, expired bool) {
	a.mu.Lock()
	defer a.mu.Unlock()
	events = []auditEvent{}
	if a.length == 0 {
		return events, false, false
	}
	if after != 0 && after < a.ring[a.start].Seq-1 {
		return nil, false, true
	}
	for i := 0; i < a.length; i++ {
		ev := a.ring[(a.start+i)%auditCapacity]
		if ev.Seq <= after {
			continue
		}
		if len(events) == limit {
			hasMore = true
			break
		}
		events = append(events, ev)
	}
	return events, hasMore, false
}
