func getAuditEvents(t *testing.T, h http.Handler, query string) (*httptest.ResponseRecorder, auditResponse) {
	t.Helper()
	req := httptest.NewRequest(http.MethodGet, "/v1/audit/events"+query, nil)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
