		{"pin.put", "created"},
		{"pin.put", "updated"},
		{"pin.delete", "deleted"},
		{"gc.preview", "previewed"},
	}
	// The collect is the sixth event; re-read with a larger window.
	_, page = getAuditEvents(t, h, "?limit=10")
	if len(page.Events) != 6 {
		t.Fatalf("events = %d, want 6", len(page.Events))
	}
	wants = append(wants, want{"gc.collect", "collected"})
	for i, w := range wants {
		ev := page.Events[i]
		if ev.Action != w.action || ev.Result != w.result {
			t.Fatalf("event %d = %s/%s, want %s/%s", i, ev.Action, ev.Result, w.action, w.result)
		}
		if ev.Seq != int64(i+1) {
			t.Fatalf("event %d seq = %d, want %d", i, ev.Seq, i+1)
